package hostconn

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/liubing0806/allowops/internal/store"
	"github.com/liubing0806/allowops/internal/store/db"
)

// Fixed-shape statements of this package are generated by sqlc from
// internal/store/queries/hostconn.sql. The statements below stay hand-written:
// LISTEN takes an identifier that cannot be a bind parameter, and the three
// gateway_messages statements are matched by their exact SQL text prefix in the
// job package's query tracers. sqlc prepends a "-- name:" comment to every
// statement, which would change that prefix. The d argument is a pool or a
// transaction.

// listen subscribes the dedicated listener connection to gateway notifications.
func listen(ctx context.Context, l *pgx.Conn) error {
	_, err := l.Exec(ctx, "LISTEN "+store.NotificationChannel)
	return err
}

func insertMessage(ctx context.Context, d db.DBTX, id, origin, host, connection string, request []byte, expires time.Time) error {
	_, err := d.Exec(ctx, "INSERT INTO gateway_messages(message_id,origin_instance,host_id,connection_id,request,expires_at) VALUES ($1,$2,$3,$4,$5,$6)", id, origin, host, connection, request, expires)
	return err
}

func failMessageCapacity(ctx context.Context, d db.DBTX, id string) error {
	_, err := d.Exec(ctx, "UPDATE gateway_messages SET failure='capacity' WHERE message_id=$1", id)
	return err
}

func messageLive(ctx context.Context, d db.DBTX, id, connection string) (bool, error) {
	var live bool
	err := d.QueryRow(ctx, "SELECT EXISTS(SELECT 1 FROM gateway_messages WHERE message_id=$1 AND connection_id=$2 AND expires_at>now() AND response IS NULL AND failure='')", id, connection).Scan(&live)
	return live, err
}
